ee:message.ee:set-payload:
%dw 2.0
output application/json
---
{
	ZBAPI_BLOCK_INVOICE_GP: {
		"import": payload.ZBAPI_BLOCK_INVOICE_GP."import",
		tables: {
			T_BAPIRET: if(payload.ZBAPI_BLOCK_INVOICE_GP.tables.T_BAPIRET.*row != null)
            payload.ZBAPI_BLOCK_INVOICE_GP.tables.T_BAPIRET.*row else
            payload.ZBAPI_BLOCK_INVOICE_GP.tables.T_BAPIRET ,
		}
	}
}

%dw 2.0
output application/json
---
{
	ZBAPI_CHANGE_INVOICE_GP: {
		"import": payload.ZBAPI_CHANGE_INVOICE_GP."import",
		tables: {
			T_BAPIRET: if(payload.ZBAPI_CHANGE_INVOICE_GP.tables.T_BAPIRET.*row != null)
			payload.ZBAPI_CHANGE_INVOICE_GP.tables.T_BAPIRET.*row else
			payload.ZBAPI_CHANGE_INVOICE_GP.tables.T_BAPIRET,
		}
	}
}

%dw 2.0
output application/json
---
{
    ZBAPI_PAYMENT_NOTIF_GP: {
    "import": {
            "I_BUKRS": payload.ZBAPI_PAYMENT_NOTIF_GP."import".I_BUKRS,
            "I_EDATE": (payload.ZBAPI_PAYMENT_NOTIF_GP."import".I_EDATE replace "UTC" with "GMT") as LocalDateTime {format: "ccc MMM d HH:mm:ss O yyyy"} as String {format: "yyyyMMdd"},
            "I_MODELO": payload.ZBAPI_PAYMENT_NOTIF_GP."import".I_MODELO,
            "I_SDATE": (payload.ZBAPI_PAYMENT_NOTIF_GP."import".I_SDATE replace "UTC" with "GMT") as LocalDateTime {format: "ccc MMM d HH:mm:ss O yyyy"} as String {format: "yyyyMMdd"},
            "I_STCD1": payload.ZBAPI_PAYMENT_NOTIF_GP."import".I_STCD1,
            "I_STCD1_EXPO": payload.ZBAPI_PAYMENT_NOTIF_GP."import".I_STCD1_EXPO
    },
    tables: {
            T_BAPIRET: if(payload.ZBAPI_PAYMENT_NOTIF_GP.tables.T_BAPIRET.*row != null) payload.ZBAPI_PAYMENT_NOTIF_GP.tables.T_BAPIRET.*row else payload.ZBAPI_PAYMENT_NOTIF_GP.tables.T_BAPIRET ,
       T_PAYMNTS: do {
    var arr = if (payload.ZBAPI_PAYMENT_NOTIF_GP.tables.T_PAYMNTS.*row != null) payload.ZBAPI_PAYMENT_NOTIF_GP.tables.T_PAYMNTS.*row else payload.ZBAPI_PAYMENT_NOTIF_GP.tables.T_PAYMNTS
---
arr map ((item, index) -> {
    "XBLNR": item.XBLNR,
    "STCD1": item.STCD1,
    "NETWR": item.NETWR,
    "WAERK": item.WAERK,
    "PDATE": ((item.PDATE replace "UTC" with "GMT") as LocalDateTime {format: "ccc MMM d HH:mm:ss O yyyy"} as String {format: "yyyyMMdd"})  default null
    })
    }
    }
}
}

%dw 2.0
output application/json
---
{
    ZBAPI_SOLFACT_CHECKDATA_GP: {
        "import": payload.ZBAPI_SOLFACT_CHECKDATA_GP."import",
        "export": payload.ZBAPI_SOLFACT_CHECKDATA_GP."export",
        tables: {
            T_BAPIRET: if (payload.ZBAPI_SOLFACT_CHECKDATA_GP.tables.T_BAPIRET.*row != null)
            payload.ZBAPI_SOLFACT_CHECKDATA_GP.tables.T_BAPIRET.*row else payload.ZBAPI_SOLFACT_CHECKDATA_GP.tables.T_BAPIRET

        }
    }
}
